// This file INTENTIONALLY mixes game logic and rendering in a few places
// (see ISSUES.md #2): brick collision detection currently lives inside the
// draw loop `frame()`. This is deliberate debt, ripe for a refactor.

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Discrete AABB test: it only says WHETHER the ball and the brick overlap,
// not WHICH face was hit. Fast balls need the swept test in step() instead.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves the ball against the live bricks: the first brick touched (in
// brick order) is destroyed and scored, the ball bounces on the face with the
// smallest penetration (equal penetrations mean a corner hit: both axes are
// inverted) and is pushed back out of the brick.
//
// One brick per pass: a seam of the grid (BRICK_GAP = 8 < ball diameter = 14)
// makes the ball overlap two bricks at once, and a second resolution in the
// same pass would invert the same axis twice and let the ball through.
function resolveBricks(state) {
  const { ball } = state;
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Penetration depth per axis; the face is the axis with the least
    // penetration, and equal penetrations are a corner.
    const px = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const py = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
    const corner = Math.abs(px - py) <= 1e-9;
    const onX = corner || px < py;

    // Push the ball back to the face it entered through (the face it is
    // moving away from), then invert that axis. A corner pushes on both.
    if (onX) {
      if (ball.vx > 0) ball.x = brick.x - ball.r;
      else if (ball.vx < 0) ball.x = brick.x + brick.w + ball.r;
      ball.vx = -ball.vx;
    }
    if (corner || !onX) {
      if (ball.vy > 0) ball.y = brick.y - ball.r;
      else if (ball.vy < 0) ball.y = brick.y + brick.h + ball.r;
      ball.vy = -ball.vy;
    }
    return;
  }
}

