content.text:
// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Discrete AABB test: it only says WHETHER the ball and the brick overlap,
// not WHICH face was hit. Fast balls need the swept test in step() instead.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves the ball against the live bricks for the movement from (prevX,
// prevY) to the ball's current position. The EARLIEST contact along that
// movement wins — one brick per pass, so a seam of the grid (BRICK_GAP = 8 <
// ball diameter = 14) can never invert the same axis twice. The brick is
// destroyed and scored, the ball bounces on the face it entered through (a
// corner inverts both axes) and is pushed back out of the brick.
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const vx = ball.x - prevX;
  const vy = ball.y - prevY;

  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptContact(ball, prevX, prevY, vx, vy, brick);
    if (hit && (best === null || hit.t < best.t)) best = { brick, hit };
  }
  if (best === null) return;

  const { brick, hit } = best;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Push the ball back to the face it entered through, then invert that
  // axis. The entered face follows the sign of the velocity component: a
  // positive vx means the ball came from the left, and so on.
  if (hit.axis === 'x' || hit.axis === 'both') {
    if (vx > 0) ball.x = brick.x - ball.r;
    else if (vx < 0) ball.x = brick.x + brick.w + ball.r;
  }
  if (hit.axis === 'y' || hit.axis === 'both') {
    if (vy > 0) ball.y = brick.y - ball.r;
    else if (vy < 0) ball.y = brick.y + brick.h + ball.r;
  }
  if (hit.axis === 'x') ball.vx = -ball.vx;
  else if (hit.axis === 'y') ball.vy = -ball.vy;
  else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// Swept segment test: does the ball's center, moving from (prevX, prevY) by
// (vx, vy), touch the brick's AABB inflated by the ball radius? Standard slab
// test (Gomez, "Swept AABB"): the movement is continuous, so a fast ball can
// never jump over a brick (tunneling). Returns the entry time t in [0, 1] and
// the entry axis ('x', 'y' or 'both' for a corner hit), or null.
function sweptContact(ball, prevX, prevY, vx, vy, brick) {
  const left = brick.x - ball.r;
  const right = brick.x + brick.w + ball.r;
  const top = brick.y - ball.r;
  const bottom = brick.y + brick.h + ball.r;

  // Entry time per axis; null = the center already sits inside the slab.
  let tx = null;
  let ty = null;
  let tExit = 1;

  if (vx === 0) {
    if (prevX <= left || prevX >= right) return null;
  } else {
    let t1 = (left - prevX) / vx;
    let t2 = (right - prevX) / vx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > 1 || t2 < 0) return null;
    tx = t1;
    tExit = Math.min(tExit, t2);
  }

  if (vy === 0) {
    if (prevY <= top || prevY >= bottom) return null;
  } else {
    let t1 = (top - prevY) / vy;
    let t2 = (bottom - prevY) / vy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > 1 || t2 < 0) return null;
    ty = t1;
    tExit = Math.min(tExit, t2);
  }

  const tEntry = Math.max(0, tx ?? 0, ty ?? 0);
  if (tEntry > tExit) return null;

  // The face is the axis with the latest entry time (the first face crossed);
  // equal entry times mean the corner was hit: both axes invert.
  let axis;
  if (tx !== null && ty !== null) {
    axis = Math.abs(tx - ty) <= 1e-9 ? 'both' : tx > ty ? 'x' : 'y';
  } else {
    axis = tx !== null ? 'x' : 'y';
  }
  return { t: tEntry, axis };
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

